    '.team"}], "definitions": {"10_mv_batting.sql": "-- METRIC VIEW = governed semantic object. Define ea'
    'ch KPI ONCE here; every dashboard, notebook, Genie space\\n-- and BI tool then gets the same answer. '
    'Query with: SELECT dim, MEASURE(measure) FROM view GROUP BY dim.\\n-- Key idea: measures are aggregat'
    'ions evaluated at QUERY time at whatever grain the caller groups by.\\nCREATE OR REPLACE VIEW {{catal'
    'og}}.semantic.mv_batting\\nWITH METRICS\\nLANGUAGE YAML\\nAS $$\\nversion: 1.1\\ncomment: \\"Batting metri'
    'cs. Source grain is player-season-stint. Ratios are computed from summed components, never averaged.'
    '\\"\\nsource: {{catalog}}.gold.fact_batting_season\\n\\njoins:\\n  - name: player\\n    source: {{catalog}'
    "}.gold.dim_player\\n    'on': source.player_key = player.player_key\\n    rely:\\n      at_most_one_mat"
    "ch: true\\n  - name: team\\n    source: {{catalog}}.gold.dim_team_season\\n    'on': source.team_season"
    '_key = team.team_season_key\\n    rely:\\n      at_most_one_match: true\\n  - name: calendar\\n    sourc'
    "e: {{catalog}}.gold.dim_season\\n    'on': source.season = calendar.season\\n    rely:\\n      at_most_"
    'one_match: true\\n\\nfields:\\n  - name: season\\n    expr: source.season\\n    display_name: \\"Season\\"\\'
    'n    synonyms: [\\"year\\"]\\n  - name: decade\\n    expr: calendar.decade\\n    display_name: \\"Decade\\"'
    '\\n  - name: baseball_era\\n    expr: calendar.era\\n    display_name: \\"Baseball Era\\"\\n    comment: \\'
    '"Business-defined era classification, see glossary term Era.\\"\\n  - name: player_name\\n    expr: pla'
    'yer.full_name\\n    display_name: \\"Player\\"\\n    synonyms: [\\"batter\\", \\"hitter\\", \\"name\\"]\\n  - n'
    'ame: batting_hand\\n    expr: player.batting_hand\\n    display_name: \\"Bats\\"\\n    synonyms: [\\"hande'
    'dness\\"]\\n  - name: birth_country\\n    expr: player.birth_country\\n    display_name: \\"Birth Country'
    '\\"\\n  - name: team_name\\n    expr: team.team_name\\n    display_name: \\"Team\\"\\n  - name: franchise\\n'
    '    expr: team.franchise_name\\n    display_name: \\"Franchise\\"\\n  - name: league\\n    expr: team.lea'
    'gue_id\\n    display_name: \\"League\\"\\n  - name: division\\n    expr: team.division_id\\n    display_na'
    'me: \\"Division\\"\\n\\nmeasures:\\n  - name: games\\n    expr: SUM(g)\\n    display_name: \\"Games\\"\\n  - n'
    'ame: at_bats\\n    expr: SUM(ab)\\n    display_name: \\"At Bats\\"\\n    synonyms: [\\"AB\\"]\\n  - name: pl'
    'ate_appearances\\n    expr: SUM(plate_appearances)\\n    display_name: \\"Plate Appearances\\"\\n    syno'
    'nyms: [\\"PA\\"]\\n  - name: runs\\n    expr: SUM(r)\\n    display_name: \\"Runs\\"\\n  - name: hits\\n    ex'
    'pr: SUM(h)\\n    display_name: \\"Hits\\"\\n    synonyms: [\\"H\\"]\\n  - name: home_runs\\n    expr: SUM(hr'
    ')\\n    display_name: \\"Home Runs\\"\\n    synonyms: [\\"HR\\", \\"homers\\", \\"dingers\\"]\\n  - name: rbi\\n'
    '    expr: SUM(rbi)\\n    display_name: \\"RBI\\"\\n    synonyms: [\\"runs batted in\\"]\\n  - name: stolen_'
    'bases\\n    expr: SUM(sb)\\n    display_name: \\"Stolen Bases\\"\\n    synonyms: [\\"SB\\", \\"steals\\"]\\n  '
    '- name: walks\\n    expr: SUM(bb)\\n    display_name: \\"Walks\\"\\n    synonyms: [\\"BB\\", \\"bases on bal'
    'ls\\"]\\n  - name: strikeouts\\n    expr: SUM(so)\\n    display_name: \\"Strikeouts\\"\\n    synonyms: [\\"S'
    'O\\", \\"K\\"]\\n  - name: batting_avg\\n    expr: SUM(h) / NULLIF(SUM(ab), 0)\\n    display_name: \\"Batti'
    'ng Average\\"\\n    synonyms: [\\"AVG\\", \\"BA\\"]\\n    comment: \\"Hits divided by at bats. Never average'
    ' player averages: always divide summed hits by summed at bats.\\"\\n  - name: on_base_pct\\n    expr: ('
    'COALESCE(SUM(h), 0) + COALESCE(SUM(bb), 0) + COALESCE(SUM(hbp), 0)) / NULLIF(COALESCE(SUM(ab), 0) + '
    'COALESCE(SUM(bb), 0) + COALESCE(SUM(hbp), 0) + COALESCE(SUM(sf), 0), 0)\\n    display_name: \\"On-Base'
    ' Percentage\\"\\n    synonyms: [\\"OBP\\"]\\n  - name: slugging_pct\\n    expr: SUM(total_bases) / NULLIF('
    'SUM(ab), 0)\\n    display_name: \\"Slugging Percentage\\"\\n    synonyms: [\\"SLG\\"]\\n  - name: ops\\n    '
    'expr: MEASURE(on_base_pct) + MEASURE(slugging_pct)\\n    display_name: \\"OPS\\"\\n    synonyms: [\\"on-b'
    'ase plus slugging\\"]\\n    comment: \\"Composed measure: built from two earlier measures with MEASURE('
    '). Change OBP once, OPS follows.\\"\\n  - name: isolated_power\\n    expr: MEASURE(slugging_pct) - MEAS'
    'URE(batting_avg)\\n    display_name: \\"Isolated Power\\"\\n    synonyms: [\\"ISO\\"]\\n  - name: home_run_'
    'rate\\n    expr: SUM(hr) * 1.0 / NULLIF(SUM(plate_appearances), 0)\\n    display_name: \\"Home Run Rate'
    '\\"\\n  - name: strikeout_rate\\n    expr: SUM(so) * 1.0 / NULLIF(SUM(plate_appearances), 0)\\n    displ'
    'ay_name: \\"Strikeout Rate\\"\\n    synonyms: [\\"K%\\"]\\n  - name: walk_rate\\n    expr: SUM(bb) * 1.0 / '
    'NULLIF(SUM(plate_appearances), 0)\\n    display_name: \\"Walk Rate\\"\\n    synonyms: [\\"BB%\\"]\\n  - nam'
    'e: stolen_base_success_rate\\n    expr: SUM(sb) * 1.0 / NULLIF(SUM(sb) + SUM(cs), 0)\\n    display_nam'
    'e: \\"Stolen Base Success Rate\\"\\n  - name: batters\\n    expr: COUNT(DISTINCT source.player_key)\\n   '
    ' display_name: \\"Distinct Batters\\"\\n    comment: \\"Non-additive: distinct counts cannot be summed a'
    'cross groups. The metric view handles that for you.\\"\\n  - name: home_runs_regular_stints\\n    expr:'
    ' SUM(hr) FILTER (WHERE ab >= 400)\\n    display_name: \\"Home Runs (400+ AB stints)\\"\\n    comment: \\"'
    'Filtered measure example: only rows with at least 400 at bats.\\"\\n  - name: cumulative_home_runs\\n  '
    '  expr: SUM(hr)\\n    display_name: \\"Cumulative Home Runs\\"\\n    comment: \\"Window measure: running '
    'total ordered by season. Group by season to see the curve.\\"\\n    window:\\n      - order: season\\n  '
    '      range: cumulative\\n$$;\\n", "20_mv_pitching.sql": "CREATE OR REPLACE VIEW {{catalog}}.semantic.'
    'mv_pitching\\nWITH METRICS\\nLANGUAGE YAML\\nAS $$\\nversion: 1.1\\ncomment: \\"Pitching metrics. Source g'
    'rain is player-season-stint. innings = ipouts / 3, so every rate uses outs, not decimal innings.\\"\\n'
    'source: {{catalog}}.gold.fact_pitching_season\\n\\njoins:\\n  - name: player\\n    source: {{catalog}}.g'
    "old.dim_player\\n    'on': source.player_key = player.player_key\\n    rely:\\n      at_most_one_match:"
    " true\\n  - name: team\\n    source: {{catalog}}.gold.dim_team_season\\n    'on': source.team_season_ke"
    'y = team.team_season_key\\n    rely:\\n      at_most_one_match: true\\n  - name: calendar\\n    source: '
    "{{catalog}}.gold.dim_season\\n    'on': source.season = calendar.season\\n    rely:\\n      at_most_one"
    '_match: true\\n\\nfields:\\n  - name: season\\n    expr: source.season\\n    display_name: \\"Season\\"\\n  '
    '  synonyms: [\\"year\\"]\\n  - name: decade\\n    expr: calendar.decade\\n    display_name: \\"Decade\\"\\n '
    ' - name: baseball_era\\n    expr: calendar.era\\n    display_name: \\"Baseball Era\\"\\n  - name: player_'
    'name\\n    expr: player.full_name\\n    display_name: \\"Pitcher\\"\\n    synonyms: [\\"player\\", \\"name\\"'
    ']\\n  - name: throws\\n    expr: player.throws\\n    display_name: \\"Throws\\"\\n  - name: team_name\\n   '
    ' expr: team.team_name\\n    display_name: \\"Team\\"\\n  - name: franchise\\n    expr: team.franchise_nam'
    'e\\n    display_name: \\"Franchise\\"\\n  - name: league\\n    expr: team.league_id\\n    display_name: \\"'
    'League\\"\\n\\nmeasures:\\n  - name: games\\n    expr: SUM(g)\\n    display_name: \\"Games\\"\\n  - name: gam'
    'es_started\\n    expr: SUM(gs)\\n    display_name: \\"Games Started\\"\\n  - name: wins\\n    expr: SUM(w)'
    '\\n    display_name: \\"Wins\\"\\n  - name: losses\\n    expr: SUM(l)\\n    display_name: \\"Losses\\"\\n  - '
    'name: saves\\n    expr: SUM(sv)\\n    display_name: \\"Saves\\"\\n  - name: complete_games\\n    expr: SUM'
    '(cg)\\n    display_name: \\"Complete Games\\"\\n  - name: shutouts\\n    expr: SUM(sho)\\n    display_name'
    ': \\"Shutouts\\"\\n  - name: strikeouts\\n    expr: SUM(so)\\n    display_name: \\"Strikeouts\\"\\n    synon'
    'yms: [\\"K\\", \\"SO\\"]\\n  - name: walks\\n    expr: SUM(bb)\\n    display_name: \\"Walks\\"\\n    synonyms:'
    ' [\\"BB\\"]\\n  - name: hits_allowed\\n    expr: SUM(h)\\n    display_name: \\"Hits Allowed\\"\\n  - name: h'
    'ome_runs_allowed\\n    expr: SUM(hr)\\n    display_name: \\"Home Runs Allowed\\"\\n  - name: earned_runs\\'
    'n    expr: SUM(er)\\n    display_name: \\"Earned Runs\\"\\n  - name: innings_pitched\\n    expr: SUM(ipou'
    'ts) / 3.0\\n    display_name: \\"Innings Pitched\\"\\n    synonyms: [\\"IP\\"]\\n  - name: era\\n    expr: 2'
